#!/usr/bin/env python3
"""
benchmark.py

Multi-API LLM benchmark harness with SSE streaming TTFT measurement.
Uses only Python stdlib (Python 3.9+).
"""

import argparse
import concurrent.futures
import datetime
import json
import os
import socket
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, List, Optional

PROMPT = "Reply with exactly one sentence about the color blue."


def now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def round_ms(seconds: float) -> float:
    return round(seconds * 1000.0, 3)


def timeout_message(timeout_seconds: float) -> str:
    return f"Connection timeout after {int(timeout_seconds * 1000)}ms"


def extract_delta_text(api_type: str, event_obj: Dict[str, Any]) -> Optional[str]:
    """
    Extract text delta from one SSE JSON object for supported API types.
    Returns:
      - str for a text delta (including empty string if present)
      - None if event has no text delta
    """
    if api_type == "chat_completions":
        choices = event_obj.get("choices")
        if isinstance(choices, list):
            for choice in choices:
                if not isinstance(choice, dict):
                    continue
                delta = choice.get("delta")
                if isinstance(delta, dict):
                    content = delta.get("content")
                    if isinstance(content, str):
                        return content
        return None

    if api_type == "responses":
        event_type = event_obj.get("type")

        # Required format from prompt
        if event_type == "content_block_delta":
            delta = event_obj.get("delta")
            if isinstance(delta, dict):
                text = delta.get("text")
                if isinstance(text, str):
                    return text

        # Extra compatibility (harmless if unused)
        if event_type in ("response.output_text.delta", "output_text.delta"):
            delta = event_obj.get("delta")
            if isinstance(delta, str):
                return delta
            if isinstance(delta, dict):
                text = delta.get("text")
                if isinstance(text, str):
                    return text

        return None

    return None


def make_error_result(
    model_id: str,
    api_type: str,
    error: str,
    total_ms: float = 0.0,
) -> Dict[str, Any]:
    return {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": round(total_ms, 3),
        "first_token": None,
        "full_response": None,
        "error": error,
    }


def benchmark_model(model_cfg: Dict[str, Any], prompt: str, timeout: float) -> Dict[str, Any]:
    model_id = str(model_cfg.get("id", "<missing-id>"))
    api_type = str(model_cfg.get("api_type", "<missing-api-type>"))

    required_fields = ["id", "api_type", "base_url", "api_key_env"]
    missing = [f for f in required_fields if not model_cfg.get(f)]
    if missing:
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            error=f"Invalid model config: missing fields {missing}",
            total_ms=0.0,
        )

    if api_type not in ("chat_completions", "responses"):
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            error=f"Unsupported api_type: {api_type}",
            total_ms=0.0,
        )

    api_key_env = str(model_cfg["api_key_env"])
    api_key = os.getenv(api_key_env)
    if not api_key:
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            error=f"Missing API key in environment variable: {api_key_env}",
            total_ms=0.0,
        )

    base_url = str(model_cfg["base_url"]).rstrip("/")
    if api_type == "chat_completions":
        url = f"{base_url}/v1/chat/completions"
        payload: Dict[str, Any] = {
            "model": model_id,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
        }
    else:
        url = f"{base_url}/v1/responses"
        payload = {
            "model": model_id,
            "input": prompt,
            "stream": True,
        }

    if "temperature" in model_cfg:
        payload["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg:
        payload["max_tokens"] = model_cfg["max_tokens"]

    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }

    # Default auth header
    if "api_key_header" in model_cfg:
        key_header = str(model_cfg.get("api_key_header"))
        key_prefix = str(model_cfg.get("api_key_prefix", ""))
        headers[key_header] = f"{key_prefix}{api_key}"
    else:
        headers["Authorization"] = f"Bearer {api_key}"

    # Optional extra headers from config
    extra_headers = model_cfg.get("headers")
    if isinstance(extra_headers, dict):
        for k, v in extra_headers.items():
            headers[str(k)] = str(v)

    body_bytes = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(url=url, data=body_bytes, headers=headers, method="POST")

    first_token: Optional[str] = None
    first_token_time: Optional[float] = None
    chunks: List[str] = []

    t_start = time.perf_counter()  # immediately before HTTP request
    deadline = t_start + timeout

    try:
        with urllib.request.urlopen(request, timeout=timeout) as resp:
            while True:
                if time.perf_counter() > deadline:
                    raise TimeoutError(timeout_message(timeout))

                line_bytes = resp.readline()
                if not line_bytes:
                    break

                line = line_bytes.decode("utf-8", errors="replace").strip()
                if not line or line.startswith(":"):
                    continue
                if not line.startswith("data:"):
                    continue

                payload_str = line[5:].strip()
                if not payload_str:
                    continue
                if payload_str == "[DONE]":
                    break

                try:
                    event_obj = json.loads(payload_str)
                except json.JSONDecodeError as e:
                    raise ValueError(f"JSON parse error in SSE stream: {e.msg}")

                delta_text = extract_delta_text(api_type, event_obj)
                if delta_text is None:
                    continue

                if delta_text != "":
                    chunks.append(delta_text)
                    if first_token is None and delta_text.strip():
                        first_token_time = time.perf_counter()
                        first_token = delta_text.strip()

        t_end = time.perf_counter()
        ttft_ms = round_ms(first_token_time - t_start) if first_token_time is not None else None
        total_ms = round_ms(t_end - t_start)
        full_response = "".join(chunks)

        return {
            "model_id": model_id,
            "api_type": api_type,
            "status": "ok",
            "ttft_ms": ttft_ms,
            "total_ms": total_ms,
            "first_token": first_token,
            "full_response": full_response,
            "error": None,
        }

    except urllib.error.HTTPError as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        body = ""
        try:
            body = e.read().decode("utf-8", errors="replace").strip()
        except Exception:
            pass
        msg = f"HTTP {e.code}: {e.reason}"
        if body:
            msg += f" | {body[:300]}"
        return make_error_result(model_id, api_type, msg, total_ms)

    except urllib.error.URLError as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        if isinstance(e.reason, socket.timeout):
            msg = timeout_message(timeout)
        else:
            msg = f"Connection error: {e.reason}"
        return make_error_result(model_id, api_type, msg, total_ms)

    except socket.timeout:
        total_ms = round_ms(time.perf_counter() - t_start)
        return make_error_result(model_id, api_type, timeout_message(timeout), total_ms)

    except TimeoutError as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        return make_error_result(model_id, api_type, str(e), total_ms)

    except ValueError as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        return make_error_result(model_id, api_type, str(e), total_ms)

    except Exception as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        return make_error_result(model_id, api_type, f"Unexpected error: {e}", total_ms)


def build_summary(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok = sum(1 for r in results if r.get("status") == "ok")
    errors = total - ok

    ttft_rows = [
        r for r in results
        if r.get("status") == "ok" and isinstance(r.get("ttft_ms"), (int, float))
    ]

    if ttft_rows:
        avg_ttft = round(sum(float(r["ttft_ms"]) for r in ttft_rows) / len(ttft_rows), 3)
        fastest_model = min(ttft_rows, key=lambda r: float(r["ttft_ms"]))["model_id"]
        slowest_model = max(ttft_rows, key=lambda r: float(r["ttft_ms"]))["model_id"]
    else:
        avg_ttft = None
        fastest_model = None
        slowest_model = None

    return {
        "total": total,
        "ok": ok,
        "errors": errors,
        "avg_ttft_ms": avg_ttft,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def load_models(config_path: str) -> List[Dict[str, Any]]:
    with open(config_path, "r", encoding="utf-8") as f:
        cfg = json.load(f)

    models = cfg.get("models")
    if not isinstance(models, list):
        raise ValueError("Config must contain a top-level 'models' list.")
    return models


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Benchmark LLM models across Chat Completions and Responses APIs with TTFT."
    )
    parser.add_argument("--config", required=True, help="Path to model config JSON.")
    parser.add_argument(
        "--output",
        default="benchmark_results.json",
        help="Output JSON path (default: benchmark_results.json).",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=30.0,
        help="Per-model timeout in seconds (default: 30).",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="Parallel workers (ThreadPoolExecutor, default: 1).",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    if args.workers < 1:
        print("Error: --workers must be >= 1")
        return 1
    if args.timeout <= 0:
        print("Error: --timeout must be > 0")
        return 1

    try:
        models = load_models(args.config)
    except Exception as e:
        print(f"Failed to load config: {e}")
        return 1

    run_id = str(uuid.uuid4())
    timestamp = now_iso()

    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as executor:
        future_to_index = {
            executor.submit(benchmark_model, model_cfg, PROMPT, args.timeout): i
            for i, model_cfg in enumerate(models)
        }

        for future in concurrent.futures.as_completed(future_to_index):
            idx = future_to_index[future]
            model_cfg = models[idx]
            model_id = str(model_cfg.get("id", "<missing-id>"))
            api_type = str(model_cfg.get("api_type", "<missing-api-type>"))

            try:
                results[idx] = future.result()
            except Exception as e:
                # Safety net: never crash entire run because of one model
                results[idx] = make_error_result(
                    model_id=model_id,
                    api_type=api_type,
                    error=f"Worker failure: {e}",
                    total_ms=0.0,
                )

    finalized_results: List[Dict[str, Any]] = []
    for i, item in enumerate(results):
        if item is not None:
            finalized_results.append(item)
        else:
            model_cfg = models[i]
            finalized_results.append(
                make_error_result(
                    model_id=str(model_cfg.get("id", "<missing-id>")),
                    api_type=str(model_cfg.get("api_type", "<missing-api-type>")),
                    error="Unknown worker error",
                    total_ms=0.0,
                )
            )

    output_obj = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": PROMPT,
        "results": finalized_results,
        "summary": build_summary(finalized_results),
    }

    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(output_obj, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print(f"Failed to write output file '{args.output}': {e}")
        return 1

    print(f"Wrote benchmark results to: {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
